class Solution:
    def diagonalPrime(self, nums: List[List[int]]) -> int:
        def is_prime(v):
            if v < 2: return False
            d = 2
            while d * d <= v:
                if v % d == 0: return False
                d += 1
            return True
        n = len(nums)
        best = 0
        for i in range(n):
            for v in (nums[i][i], nums[i][n - 1 - i]):
                if v > best and is_prime(v):
                    best = v
        return best

