class Solution:
    def diagonalPrime(self, nums: List[List[int]]) -> int:
        n = len(nums)
        vals = [nums[i][i] for i in range(n)] + [nums[i][n - 1 - i] for i in range(n)]
        maxV = max(vals)
        sieve = bytearray([1]) * (maxV + 1)
        sieve[0:min(2, maxV + 1)] = b"\x00" * min(2, maxV + 1)
        d = 2
        while d * d <= maxV:
            if sieve[d]:
                sieve[d*d::d] = b"\x00" * len(sieve[d*d::d])
            d += 1
        return max((v for v in vals if sieve[v]), default=0)

