class Solution {
public:
    int diagonalPrime(vector<vector<int>>& nums) {
        int n = nums.size(), maxV = 0;
        vector<int> vals;
        for (int i = 0; i < n; i++) {
            vals.push_back(nums[i][i]); vals.push_back(nums[i][n - 1 - i]);
            maxV = max({maxV, nums[i][i], nums[i][n - 1 - i]});
        }
        vector<bool> comp(maxV + 1, false);
        for (long long d = 2; d <= maxV; d++)
            if (!comp[d]) for (long long j = d * d; j <= maxV; j += d) comp[j] = true;
        int best = 0;
        for (int v : vals) if (v >= 2 && !comp[v]) best = max(best, v);
        return best;
    }
};

