class Solution {
    public int diagonalPrime(int[][] nums) {
        int n = nums.length, maxV = 0;
        List<Integer> vals = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            vals.add(nums[i][i]); vals.add(nums[i][n - 1 - i]);
            maxV = Math.max(maxV, Math.max(nums[i][i], nums[i][n - 1 - i]));
        }
        boolean[] comp = new boolean[maxV + 1];
        for (int d = 2; d <= maxV; d++)
            if (!comp[d]) for (long j = (long) d * d; j <= maxV; j += d) comp[(int) j] = true;
        int best = 0;
        for (int v : vals) if (v >= 2 && !comp[v]) best = Math.max(best, v);
        return best;
    }
}

